import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent {
  isJumping = false;
  highlights = [
    {
      title: 'Build-your-own pizza',
      text: 'Select extra ingredients and see them appear directly on the pizza preview.'
    },
    {
      title: 'Fake banking checkout',
      text: 'Customers can place items in the cart and complete a safe demo payment flow.'
    },
    {
      title: 'Angular requirements covered',
      text: 'Routing, ngModel, interceptors, services, API calls, and error handling are already wired in.'
    }
  ];
  makePizzaJump(): void {
    if (this.isJumping) return;

    this.isJumping = true;

    
    setTimeout(() => {
      this.isJumping = false;
    }, 500);
  }
}
<section class="hero container">
  <div class="hero-copy">
    <h1>Order artisan pizza with a live topping preview and a banking checkout.</h1>
    <p>
      This front end demonstrates Angular routing, API services, JWT authentication, dynamic pizza customization,
      cart management, and a demo payment experience.
    </p>
    <div class="hero-actions">
      <a class="btn btn-primary" routerLink="/menu">Open menu</a>
      <a class="btn btn-secondary" routerLink="/login">Demo login</a>
    </div>
  </div>

  <div class="hero-visual card">
  <div class="cat-pizza-side-by-side">
    
    <div class="cat-container">
      <img src="assets/images/photo_5409257004758405462_y.jpg" alt="Cat Chef" class="cat-chef">
    </div>

    <div class="pizza-container" (click)="makePizzaJump()">
      <div class="plate">
        <div class="pizza" [class.jumping]="isJumping">
          <span class="topping pepperoni">●</span>
          <span class="topping basil">✦</span>
          <span class="topping olive">◉</span>
          <span class="topping mozzarella">✹</span>
        </div>
      </div>
    </div>

  </div>

  <div class="hero-note">
    <strong>Demo credentials</strong>
    <span>demo&#64;pizzeria.com</span>
    <span>pizza123</span>
  </div>
</div>
</section>

<section class="container features">
  <div class="heading">
    <h2 class="section-title">What this front end includes</h2>
    <p class="section-subtitle">
      The project is structured to satisfy a course-style Angular checklist while still looking like a real product.
    </p>
  </div>

  <div class="feature-grid">
    @for (highlight of highlights; track highlight.title) {
      <article class="card feature-card">
        <h3>{{ highlight.title }}</h3>
        <p>{{ highlight.text }}</p>
      </article>
    }
  </div>
</section>
